def anti_shuffle(s):
    def sort_word(word):
        return ''.join(sorted(word))

    words = s.split(' ')
    ordered_words = []

    for word in words:
        if word:  # Check if the word is not empty
            ordered_words.append(sort_word(word))
        else:
            ordered_words.append('')  # Maintain the empty space for consecutive spaces

    result = ' '.join(ordered_words)
    return result
